-- Parte 2/3 — funciones, triggers y vistas del nucleo v0.2
BEGIN;
ALTER TABLE public.articulos ADD COLUMN IF NOT EXISTS codigo text;
ALTER TABLE public.articulos ADD COLUMN IF NOT EXISTS clasificacion text;
ALTER TABLE public.articulos ADD COLUMN IF NOT EXISTS unidad_base_id text;
INSERT INTO public.unidades_medida VALUES('UNIDAD-KG','KG','Kilogramo',2,true),('UNIDAD-PZA','PZA','Pieza',0,true),('UNIDAD-TRABAJO','TRABAJO','Trabajo de produccion',3,true) ON CONFLICT DO NOTHING;
UPDATE public.articulos SET codigo=COALESCE(codigo,id),clasificacion=COALESCE(clasificacion,CASE WHEN COALESCE(unidad,'') ILIKE 'KG%' THEN 'MATERIA_PRIMA' ELSE 'PRODUCTO_EN_PROCESO' END),unidad_base_id=COALESCE(unidad_base_id,CASE WHEN COALESCE(unidad,'') ILIKE 'KG%' THEN 'UNIDAD-KG' ELSE 'UNIDAD-PZA' END);
ALTER TABLE public.articulos ALTER COLUMN codigo SET NOT NULL;
ALTER TABLE public.articulos ALTER COLUMN clasificacion SET NOT NULL;
ALTER TABLE public.articulos ALTER COLUMN unidad_base_id SET NOT NULL;

CREATE OR REPLACE FUNCTION public.resolver_cantidad_base(p_articulo_id text,p_cantidad numeric,p_unidad_capturada_id text) RETURNS TABLE(factor numeric,cantidad_base numeric,unidad_base_id text) LANGUAGE plpgsql STABLE AS $$DECLARE v_base text;BEGIN IF p_cantidad IS NULL OR p_cantidad<=0 THEN RAISE EXCEPTION 'CANTIDAD_INVALIDA';END IF;SELECT a.unidad_base_id INTO v_base FROM public.articulos a WHERE a.id=p_articulo_id AND a.activo;IF NOT FOUND THEN RAISE EXCEPTION 'ARTICULO_INEXISTENTE_O_INACTIVO';END IF;IF p_unidad_capturada_id=v_base THEN RETURN QUERY SELECT 1::numeric,round(p_cantidad,3),v_base;RETURN;END IF;RETURN QUERY SELECT au.factor_conversion,round(p_cantidad*au.factor_conversion,3),au.unidad_base_id FROM public.articulo_unidades_operativas au WHERE au.articulo_id=p_articulo_id AND au.unidad_operativa_id=p_unidad_capturada_id AND au.activo;IF NOT FOUND THEN RAISE EXCEPTION 'CONVERSION_OPERATIVA_NO_CONFIGURADA';END IF;END$$;
CREATE OR REPLACE VIEW public.vw_inventario_actual AS SELECT lote_id,unidad_logistica_id,ubicacion_id,estado_inventario,unidad_id,sum(cantidad_firmada)::numeric(18,3) existencia FROM(SELECT lote_id,unidad_logistica_id,ubicacion_destino_id ubicacion_id,estado_destino estado_inventario,unidad_id,cantidad cantidad_firmada FROM public.movimientos_inventario WHERE estado_movimiento='CONFIRMADO' AND ubicacion_destino_id IS NOT NULL UNION ALL SELECT lote_id,unidad_logistica_id,ubicacion_origen_id,estado_origen,unidad_id,-cantidad FROM public.movimientos_inventario WHERE estado_movimiento='CONFIRMADO' AND ubicacion_origen_id IS NOT NULL)x GROUP BY lote_id,unidad_logistica_id,ubicacion_id,estado_inventario,unidad_id;
CREATE OR REPLACE FUNCTION public.validar_saldo_movimiento_confirmado() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE v_saldo numeric(18,3);BEGIN IF NEW.estado_movimiento<>'CONFIRMADO' OR NEW.ubicacion_origen_id IS NULL THEN RETURN NEW;END IF;SELECT COALESCE(sum(existencia),0) INTO v_saldo FROM public.vw_inventario_actual WHERE lote_id=NEW.lote_id AND unidad_logistica_id IS NOT DISTINCT FROM NEW.unidad_logistica_id AND ubicacion_id=NEW.ubicacion_origen_id AND estado_inventario=NEW.estado_origen AND unidad_id=NEW.unidad_id;IF v_saldo<NEW.cantidad THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE=format('SALDO_INSUFICIENTE: disponible %s; solicitado %s',v_saldo,NEW.cantidad);END IF;RETURN NEW;END$$;
CREATE TRIGGER trg_validar_saldo_movimiento_confirmado BEFORE INSERT ON public.movimientos_inventario FOR EACH ROW EXECUTE FUNCTION public.validar_saldo_movimiento_confirmado();
CREATE OR REPLACE FUNCTION public.proteger_movimiento_confirmado() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF OLD.estado_movimiento='CONFIRMADO' THEN RAISE EXCEPTION 'MOVIMIENTO_CONFIRMADO_INMUTABLE';END IF;RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;END$$;
CREATE TRIGGER trg_proteger_movimiento_confirmado BEFORE UPDATE OR DELETE ON public.movimientos_inventario FOR EACH ROW EXECUTE FUNCTION public.proteger_movimiento_confirmado();
CREATE OR REPLACE FUNCTION public.registrar_reversion_movimiento(p_evento_id text,p_movimiento_original_id text,p_movimiento_reversion_id text,p_solicitado_por text,p_autorizado_por text,p_motivo text) RETURNS TABLE(evento_id text,movimiento_original_id text,movimiento_reversion_id text,cantidad_revertida numeric) LANGUAGE plpgsql AS $$DECLARE v public.movimientos_inventario%ROWTYPE;BEGIN IF p_solicitado_por=p_autorizado_por THEN RAISE EXCEPTION 'SEGREGACION_REQUERIDA';END IF;SELECT * INTO v FROM public.movimientos_inventario WHERE id=p_movimiento_original_id FOR UPDATE;IF NOT FOUND OR v.estado_movimiento<>'CONFIRMADO' THEN RAISE EXCEPTION 'MOVIMIENTO_NO_REVERTIBLE';END IF;IF EXISTS(SELECT 1 FROM public.movimiento_reversiones WHERE movimiento_original_id=v.id) THEN RAISE EXCEPTION 'MOVIMIENTO_YA_REVERTIDO';END IF;INSERT INTO public.movimientos_inventario(id,tipo_movimiento,lote_id,unidad_logistica_id,cantidad,unidad_id,ubicacion_origen_id,estado_origen,ubicacion_destino_id,estado_destino,estado_movimiento,fecha_efectiva,confirmado_por,movimiento_reversado_id,motivo_ajuste,creado_por) VALUES(p_movimiento_reversion_id,'REVERSION',v.lote_id,v.unidad_logistica_id,v.cantidad,v.unidad_id,v.ubicacion_destino_id,v.estado_destino,v.ubicacion_origen_id,v.estado_origen,'CONFIRMADO',now(),p_autorizado_por,v.id,p_motivo,p_solicitado_por);INSERT INTO public.movimiento_reversiones VALUES(p_evento_id,v.id,p_movimiento_reversion_id,p_solicitado_por,now(),p_autorizado_por,now(),p_motivo,'APLICADA');RETURN QUERY SELECT p_evento_id,v.id,p_movimiento_reversion_id,v.cantidad;END$$;
CREATE OR REPLACE FUNCTION public.impedir_cambio_directo_estado_lote() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF (NEW.estado_calidad,NEW.estado_liberacion) IS DISTINCT FROM (OLD.estado_calidad,OLD.estado_liberacion) AND current_setting('app.lote_calidad_autorizado',true) IS DISTINCT FROM NEW.id THEN RAISE EXCEPTION 'CAMBIO_CALIDAD_NO_AUTORIZADO';END IF;RETURN NEW;END$$;
CREATE TRIGGER trg_impedir_cambio_directo_estado_lote BEFORE UPDATE OF estado_calidad,estado_liberacion ON public.lotes FOR EACH ROW EXECUTE FUNCTION public.impedir_cambio_directo_estado_lote();
CREATE OR REPLACE FUNCTION public.registrar_evento_calidad_lote(p_evento_id text,p_lote_id text,p_estado_calidad_nuevo text,p_estado_liberacion_nuevo text,p_tipo_evento text,p_motivo text,p_usuario_id text,p_referencia_concesion text DEFAULT NULL) RETURNS public.lote_eventos_calidad LANGUAGE plpgsql AS $$DECLARE v public.lotes%ROWTYPE;e public.lote_eventos_calidad%ROWTYPE;r text;a text;BEGIN SELECT ro.nombre,ar.nombre INTO r,a FROM public.usuarios u JOIN public.roles ro ON ro.id=u.rol_id LEFT JOIN public.areas ar ON ar.id=u.area_id WHERE u.id=p_usuario_id AND u.activo;IF a IS DISTINCT FROM 'Control de Calidad' OR r IS DISTINCT FROM 'Jefe de Sistemas de Calidad e Inocuidad' THEN RAISE EXCEPTION 'USUARIO_NO_AUTORIZADO_CALIDAD';END IF;SELECT * INTO v FROM public.lotes WHERE id=p_lote_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'LOTE_INEXISTENTE';END IF;PERFORM set_config('app.lote_calidad_autorizado',p_lote_id,true);UPDATE public.lotes SET estado_calidad=p_estado_calidad_nuevo,estado_liberacion=p_estado_liberacion_nuevo WHERE id=p_lote_id;PERFORM set_config('app.lote_calidad_autorizado','',true);INSERT INTO public.lote_eventos_calidad(id,lote_id,estado_calidad_anterior,estado_calidad_nuevo,estado_liberacion_anterior,estado_liberacion_nuevo,tipo_evento,motivo,referencia_concesion,registrado_por) VALUES(p_evento_id,p_lote_id,v.estado_calidad,p_estado_calidad_nuevo,v.estado_liberacion,p_estado_liberacion_nuevo,p_tipo_evento,p_motivo,p_referencia_concesion,p_usuario_id) RETURNING * INTO e;RETURN e;END$$;
CREATE OR REPLACE FUNCTION public.fn_preparar_recepcion_material_appsheet() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN NEW.estado:=COALESCE(NULLIF(NEW.estado,''),'ACTIVA');NEW.numero_analisis:=upper(btrim(NEW.numero_analisis));NEW.codigo_lote:=btrim(NEW.codigo_lote);RETURN NEW;END$$;
CREATE OR REPLACE FUNCTION public.fn_registrar_recepcion_material() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE c numeric;b text;BEGIN SELECT cantidad_base,unidad_base_id INTO c,b FROM public.resolver_cantidad_base(NEW.articulo_id,NEW.cantidad_capturada,NEW.unidad_capturada_id);NEW.cantidad_base:=c;NEW.unidad_base_id:=b;NEW.analisis_calidad_id:='ANL-REC-'||NEW.id;NEW.lote_id:='LOT-REC-'||NEW.id;NEW.movimiento_inventario_id:='MOV-REC-'||NEW.id;INSERT INTO public.analisis_calidad_materiales(id,numero_analisis,tipo_analisis,folio_ft_al_01,articulo_id,creado_por) VALUES(NEW.analisis_calidad_id,NEW.numero_analisis,NEW.tipo_analisis,NEW.folio_ft_al_01,NEW.articulo_id,NEW.recibido_por);INSERT INTO public.lotes(id,codigo_lote,articulo_id,tipo_origen,area_origen_id,proveedor_id,fecha_recepcion,estado_calidad,estado_liberacion,lote_proveedor,analisis_calidad_id) VALUES(NEW.lote_id,NEW.codigo_lote,NEW.articulo_id,CASE WHEN NEW.tipo_analisis='MOLIENDA' THEN 'PRODUCCION_INTERNA' ELSE 'PROVEEDOR' END,NEW.area_origen_id,NEW.proveedor_id,NEW.fecha_recepcion,'CUARENTENA','BLOQUEADO',NEW.lote_proveedor,NEW.analisis_calidad_id);INSERT INTO public.movimientos_inventario(id,tipo_movimiento,lote_id,cantidad,unidad_id,ubicacion_destino_id,estado_destino,estado_movimiento,fecha_efectiva,confirmado_por,creado_por) VALUES(NEW.movimiento_inventario_id,'RECEPCION_MATERIAL',NEW.lote_id,c,b,NEW.ubicacion_cuarentena_id,'CUARENTENA','CONFIRMADO',NEW.fecha_recepcion,NEW.recibido_por,NEW.recibido_por);RETURN NEW;END$$;
CREATE TRIGGER trg_00_preparar_recepcion_material_appsheet BEFORE INSERT ON public.recepciones_materiales FOR EACH ROW EXECUTE FUNCTION public.fn_preparar_recepcion_material_appsheet();
CREATE TRIGGER trg_registrar_recepcion_material BEFORE INSERT ON public.recepciones_materiales FOR EACH ROW EXECUTE FUNCTION public.fn_registrar_recepcion_material();
CREATE OR REPLACE FUNCTION public.registrar_dictamen_calidad_material(p_analisis_id text,p_estado_dictamen text,p_fecha_dictamen date,p_inspeccionado_por text,p_confirmado_por text,p_observaciones text DEFAULT NULL) RETURNS public.analisis_calidad_materiales LANGUAGE plpgsql AS $$DECLARE v public.analisis_calidad_materiales%ROWTYPE;BEGIN UPDATE public.analisis_calidad_materiales SET estado_dictamen=p_estado_dictamen,fecha_dictamen=p_fecha_dictamen,inspeccionado_por=p_inspeccionado_por,confirmado_por=p_confirmado_por,confirmado_en=now(),observaciones=p_observaciones WHERE id=p_analisis_id AND estado_dictamen='PENDIENTE' RETURNING * INTO v;IF NOT FOUND THEN RAISE EXCEPTION 'ANALISIS_CALIDAD_INEXISTENTE_O_DICTAMINADO';END IF;RETURN v;END$$;
CREATE OR REPLACE FUNCTION public.fn_aplicar_reversion_recepcion_material() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE r public.recepciones_materiales%ROWTYPE;l public.lotes%ROWTYPE;a text;BEGIN SELECT * INTO r FROM public.recepciones_materiales WHERE id=NEW.recepcion_id FOR UPDATE;IF NOT FOUND OR r.estado<>'ACTIVA' THEN RAISE EXCEPTION 'RECEPCION_NO_REVERTIBLE';END IF;SELECT * INTO l FROM public.lotes WHERE id=r.lote_id;SELECT estado_dictamen INTO a FROM public.analisis_calidad_materiales WHERE id=r.analisis_calidad_id;IF l.estado_calidad<>'CUARENTENA' OR l.estado_liberacion<>'BLOQUEADO' OR a<>'PENDIENTE' THEN RAISE EXCEPTION 'RECEPCION_NO_REVERTIBLE';END IF;NEW.movimiento_reversion_id:='MOV-REV-REC-'||NEW.id;NEW.evento_reversion_id:='EVT-REV-REC-'||NEW.id;PERFORM * FROM public.registrar_reversion_movimiento(NEW.evento_reversion_id,r.movimiento_inventario_id,NEW.movimiento_reversion_id,NEW.solicitado_por,NEW.autorizado_por,NEW.motivo);UPDATE public.lotes SET activo=false WHERE id=r.lote_id;UPDATE public.recepciones_materiales SET estado='REVERTIDA',reversion_recepcion_id=NEW.id,revertida_en=now() WHERE id=r.id;RETURN NEW;END$$;
CREATE TRIGGER trg_aplicar_reversion_recepcion_material BEFORE INSERT ON public.reversiones_recepciones_materiales FOR EACH ROW EXECUTE FUNCTION public.fn_aplicar_reversion_recepcion_material();
CREATE OR REPLACE FUNCTION public.registrar_devolucion_interna_diferencia_peso(p_devolucion_id text,p_folio_devolucion text,p_devolucion_detalle_id text,p_movimiento_id text,p_orden_produccion_id text,p_lote_id text,p_cantidad numeric,p_unidad_id text,p_ubicacion_custodia_id text,p_ubicacion_supermercado_id text,p_metodo_determinacion text,p_registrado_por text,p_autorizado_por text,p_observaciones text DEFAULT NULL) RETURNS TABLE(devolucion_id text,movimiento_id text,cantidad_reconocida numeric,cantidad_asignada numeric) LANGUAGE plpgsql AS $$DECLARE s text;BEGIN SELECT sd.id INTO s FROM public.surtido_detalles sd JOIN public.surtidos su ON su.id=sd.surtido_id JOIN public.solicitudes_material sm ON sm.id=su.solicitud_material_id WHERE sm.orden_produccion_id=p_orden_produccion_id AND sd.lote_id=p_lote_id AND sd.unidad_id=p_unidad_id ORDER BY su.recibido_en LIMIT 1;IF s IS NULL THEN RAISE EXCEPTION 'No existe surtido compatible';END IF;INSERT INTO public.devoluciones(id,folio_devolucion,orden_produccion_id,estado_devolucion,motivo,entregado_por,entregado_en,recibido_por,recibido_en,observaciones,tipo_devolucion,es_excedente_documental,autorizado_por,autorizado_en) VALUES(p_devolucion_id,p_folio_devolucion,p_orden_produccion_id,'RECIBIDA','DIFERENCIA_POR_PESO',p_registrado_por,now(),p_registrado_por,now(),p_observaciones,'INTERNA',true,p_autorizado_por,now());INSERT INTO public.movimientos_inventario(id,tipo_movimiento,lote_id,cantidad,unidad_id,ubicacion_destino_id,estado_destino,estado_movimiento,confirmado_por,creado_por) VALUES(p_movimiento_id,'ENTRADA_DIFERENCIA_POR_PESO',p_lote_id,p_cantidad,p_unidad_id,p_ubicacion_supermercado_id,'DISPONIBLE','CONFIRMADO',p_autorizado_por,p_registrado_por);INSERT INTO public.devolucion_detalles(id,devolucion_id,lote_id,cantidad_declarada,cantidad_recibida,unidad_id,ubicacion_origen_id,ubicacion_destino_id,estado_identificacion,movimiento_inventario_id,motivo_detalle,metodo_determinacion) VALUES(p_devolucion_detalle_id,p_devolucion_id,p_lote_id,p_cantidad,p_cantidad,p_unidad_id,p_ubicacion_custodia_id,p_ubicacion_supermercado_id,'IDENTIFICADO',p_movimiento_id,'DIFERENCIA_POR_PESO',p_metodo_determinacion);INSERT INTO public.devolucion_asignaciones(id,devolucion_detalle_id,surtido_detalle_id,cantidad_asignada,metodo_asignacion,asignado_por) VALUES(p_devolucion_detalle_id||'-ASIG-1',p_devolucion_detalle_id,s,p_cantidad,'FIFO_AUTOMATICO_EXCEDENTE',p_autorizado_por);RETURN QUERY SELECT p_devolucion_id,p_movimiento_id,p_cantidad,p_cantidad;END$$;
CREATE OR REPLACE VIEW public.vw_app_trazabilidad_op AS SELECT concat_ws('|',op.id,'CONSUMO',cd.id) id,op.id orden_produccion_id,op.numero_op,op.area_id,ae.nombre area,op.articulo_id articulo_terminado_id,apt.nombre_producto articulo_terminado,'CONSUMO'::text tipo_evento,c.confirmado_en fecha_evento,cd.lote_id lote_relacionado_id,lc.codigo_lote lote_relacionado,lc.articulo_id articulo_relacionado_id,ac.nombre_producto articulo_relacionado,cd.cantidad_consumida cantidad,cd.unidad_id,cd.movimiento_inventario_id FROM public.ordenes_produccion op JOIN public.areas ae ON ae.id=op.area_id JOIN public.articulos apt ON apt.id=op.articulo_id JOIN public.consumos c ON c.orden_produccion_id=op.id JOIN public.consumo_detalles cd ON cd.consumo_id=c.id JOIN public.lotes lc ON lc.id=cd.lote_id JOIN public.articulos ac ON ac.id=lc.articulo_id UNION ALL SELECT concat_ws('|',op.id,'DEVOLUCION',dd.id),op.id,op.numero_op,op.area_id,ae.nombre,op.articulo_id,apt.nombre_producto,'DEVOLUCION_'||d.tipo_devolucion,COALESCE(d.recibido_en,d.entregado_en),dd.lote_id,ld.codigo_lote,ld.articulo_id,ad.nombre_producto,COALESCE(dd.cantidad_recibida,dd.cantidad_declarada),dd.unidad_id,dd.movimiento_inventario_id FROM public.ordenes_produccion op JOIN public.areas ae ON ae.id=op.area_id JOIN public.articulos apt ON apt.id=op.articulo_id JOIN public.devoluciones d ON d.orden_produccion_id=op.id JOIN public.devolucion_detalles dd ON dd.devolucion_id=d.id JOIN public.lotes ld ON ld.id=dd.lote_id JOIN public.articulos ad ON ad.id=ld.articulo_id;
COMMIT;
